const categories=['All apps',...new Set(apps.map(a=>a.category))];let active='All apps';
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const q=document.getElementById('search').value.trim().toLowerCase();const shown=apps.filter(a=>(active==='All apps'||a.category===active)&&(!q||`${a.name} ${a.category} ${a.description}`.toLowerCase().includes(q)));document.getElementById('appCount').textContent=`${shown.length} ${shown.length===1?'app':'apps'} · no account needed to browse`;document.getElementById('grid').innerHTML=shown.length?shown.map(a=>`<article class="card"><div class="card-top"><span class="icon" aria-hidden="true">${a.icon}</span><span class="tag">${esc(a.category)}</span></div><h3>${esc(a.name)}${a.fresh?' · New link':''}</h3><p>${esc(a.description)}</p><a class="open" href="${esc(a.url)}" target="_blank" rel="noopener">Open app ↗</a></article>`).join(''):'<p class="empty">No apps match that search.</p>'}
document.getElementById('filters').innerHTML=categories.map(c=>`<button class="filter${c===active?' active':''}" type="button" data-category="${esc(c)}">${esc(c)}</button>`).join('');document.getElementById('filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;active=b.dataset.category;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render()});document.getElementById('search').addEventListener('input',render);render();
document.getElementById('share').addEventListener('click',async()=>{try{if(navigator.share)await navigator.share({title:document.title,text:'Explore the AWE Missions app hub.',url:location.href});else{await navigator.clipboard.writeText(location.href);document.getElementById('share').textContent='Link copied'}}catch{}});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
